import type { PropsWithChildren } from 'react'

interface AppShellProps extends PropsWithChildren {
  title: string
  subtitle?: string
  roomCode?: string
  phase?: string
  role?: string
  connected?: boolean
}

export function AppShell({ title, subtitle, roomCode, phase, role, connected, children }: AppShellProps) {
  return (
    <main className="relative min-h-screen overflow-hidden bg-slate-950 text-slate-100">
      <div className="pointer-events-none absolute inset-0 bg-[radial-gradient(circle_at_10%_10%,rgba(59,130,246,0.3),transparent_28%),radial-gradient(circle_at_80%_0%,rgba(16,185,129,0.22),transparent_24%),radial-gradient(circle_at_100%_80%,rgba(250,204,21,0.16),transparent_30%)]" />
      <div className="relative mx-auto w-full max-w-6xl px-4 py-8 md:px-6">
        <header className="mb-8 rounded-2xl border border-slate-700/70 bg-slate-900/70 p-5 backdrop-blur">
          <div className="mb-4 flex flex-wrap items-center gap-2">
            {roomCode ? <span className="chip">Room {roomCode}</span> : null}
            {phase ? <span className="chip chip-brand">{phase}</span> : null}
            {role ? <span className="chip">{role}</span> : null}
            {connected !== undefined ? (
              <span className={`chip ${connected ? 'chip-ok' : 'chip-bad'}`}>{connected ? 'Realtime Connected' : 'Disconnected'}</span>
            ) : null}
          </div>

          <h1 className="text-3xl font-black tracking-tight text-white md:text-4xl">{title}</h1>
          {subtitle ? <p className="mt-2 max-w-3xl text-slate-300">{subtitle}</p> : null}
        </header>
        {children}
      </div>
    </main>
  )
}

import type { PropsWithChildren } from 'react'

interface AppShellProps extends PropsWithChildren {
  title: string
  subtitle?: string
  roomCode?: string
  phase?: string
  role?: string
  connected?: boolean
}

export function AppShell({ title, subtitle, roomCode, phase, role, connected, children }: AppShellProps) {
  return (
    <main className="relative min-h-screen overflow-hidden bg-slate-950 text-slate-100">
      <div className="pointer-events-none absolute inset-0 bg-[radial-gradient(circle_at_10%_10%,rgba(59,130,246,0.3),transparent_28%),radial-gradient(circle_at_80%_0%,rgba(16,185,129,0.22),transparent_24%),radial-gradient(circle_at_100%_80%,rgba(250,204,21,0.16),transparent_30%)]" />
      <div className="relative mx-auto w-full max-w-6xl px-4 py-8 md:px-6">
        <header className="mb-8 rounded-2xl border border-slate-700/70 bg-slate-900/70 p-5 backdrop-blur">
          <div className="mb-4 flex flex-wrap items-center gap-2">
            {roomCode ? <span className="chip">Phòng {roomCode}</span> : null}
            {phase ? <span className="chip chip-brand">{phase}</span> : null}
            {role ? <span className="chip">{role}</span> : null}
            {connected !== undefined ? (
              <span className={`chip ${connected ? 'chip-ok' : 'chip-bad'}`}>{connected ? 'Đã kết nối thời gian thực' : 'Mất kết nối'}</span>
            ) : null}
          </div>

          <h1 className="text-3xl font-black tracking-tight text-white md:text-4xl">{title}</h1>
          {subtitle ? <p className="mt-2 max-w-3xl text-slate-300">{subtitle}</p> : null}
        </header>
        {children}
      </div>
    </main>
  )
}

import type { GameOutboundMessage } from '../types/socket'

interface EventFeedProps {
  items: GameOutboundMessage[]
}

export function EventFeed({ items }: EventFeedProps) {
  const toneByEvent = (eventType: string): string => {
    if (eventType === 'TURN_CHANGE') return 'border-amber-300/40 bg-amber-500/10 text-amber-100'
    if (eventType === 'GAME_END') return 'border-emerald-300/40 bg-emerald-500/10 text-emerald-100'
    if (eventType === 'START_GAME') return 'border-blue-300/40 bg-blue-500/10 text-blue-100'
    return 'border-slate-600/60 bg-slate-800/80 text-slate-200'
  }

  return (
    <section className="rounded-2xl border border-slate-700 bg-slate-900/90 p-4">
      <h3 className="mb-3 text-lg font-semibold text-slate-100">Realtime Feed</h3>
      <div className="max-h-80 space-y-2 overflow-y-auto pr-1">
        {items.length === 0 ? <p className="text-sm text-slate-400">No events yet.</p> : null}
        {items.map((item, index) => (
          <article
            key={`${item.serverTime}-${index}`}
            className={`rounded-lg border p-2 text-sm transition ${toneByEvent(item.eventType)}`}
          >
            <div className="font-semibold">{item.eventType}</div>
            <div className="text-xs opacity-90">{item.actor}</div>
            <div className="text-[11px] opacity-70">{new Date(item.serverTime).toLocaleTimeString()}</div>
          </article>
        ))}
      </div>
    </section>
  )
}

import type { GameOutboundMessage } from '../types/socket'

interface EventFeedProps {
