    if (eventType === 'GAME_END') return 'border-emerald-300/40 bg-emerald-500/10 text-emerald-100'
    if (eventType === 'START_GAME') return 'border-blue-300/40 bg-blue-500/10 text-blue-100'
    return 'border-slate-600/60 bg-slate-800/80 text-slate-200'
  }

  return (
    <section className="rounded-2xl border border-slate-700 bg-slate-900/90 p-4">
      <h3 className="mb-3 text-lg font-semibold text-slate-100">Bảng sự kiện thời gian thực</h3>
      <div className="max-h-80 space-y-2 overflow-y-auto pr-1">
        {items.length === 0 ? <p className="text-sm text-slate-400">Chưa có sự kiện nào.</p> : null}
        {items.map((item, index) => (
          <article
            key={`${item.serverTime}-${index}`}
            className={`rounded-lg border p-2 text-sm transition ${toneByEvent(item.eventType)}`}
          >
            <div className="font-semibold">{item.eventType}</div>
            <div className="text-xs opacity-90">{item.actor}</div>
            <div className="text-[11px] opacity-70">{new Date(item.serverTime).toLocaleTimeString()}</div>
          </article>
        ))}
      </div>
    </section>
  )
}

import type { PlayerView } from '../types/room'

interface PlayerListProps {
  players: PlayerView[]
  currentTurnPlayerId?: string
}

export function PlayerList({ players, currentTurnPlayerId }: PlayerListProps) {
  return (
    <ul className="grid gap-3">
      {players.map((player, index) => {
        const isCurrent = currentTurnPlayerId === player.id
        return (
          <li
            key={player.id}
            className={`rounded-xl border p-4 transition ${
              isCurrent
                ? 'border-amber-300 bg-gradient-to-r from-amber-500/30 to-orange-500/20 shadow-[0_0_20px_rgba(251,191,36,0.25)]'
                : 'border-slate-700 bg-slate-900/80'
            }`}
          >
            <div className="flex items-center justify-between">
              <span className="font-semibold text-slate-100">
                #{index + 1} {player.nickname}
              </span>
              <span className="text-sm font-semibold text-amber-200">{player.score} pts</span>
            </div>
            <div className="mt-2 flex flex-wrap gap-2 text-xs text-slate-300">
              <span className={`rounded-full px-2 py-0.5 ${player.host ? 'bg-blue-500/20 text-blue-100' : 'bg-slate-700 text-slate-200'}`}>
                {player.host ? 'Host' : 'Player'}
              </span>
              <span className={`rounded-full px-2 py-0.5 ${player.connected ? 'bg-emerald-500/20 text-emerald-100' : 'bg-red-500/20 text-red-100'}`}>
                {player.connected ? 'Online' : 'Offline'}
              </span>
              {isCurrent ? <span className="rounded-full bg-amber-500/20 px-2 py-0.5 text-amber-100">Current Turn</span> : null}
            </div>
          </li>
        )
      })}
    </ul>
  )
}

