          <label className="grid gap-2">
            <span className="text-sm text-slate-300">Nickname</span>
            <input
              className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 outline-none transition focus:border-brand-500"
              placeholder="e.g. Captain_01"
              value={nickname}
              onChange={(e) => setNickname(e.target.value)}
              maxLength={30}
            />
          </label>

          <label className="grid gap-2">
            <span className="text-sm text-slate-300">Room Code</span>
            <input
              className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 uppercase outline-none transition focus:border-brand-500"
              placeholder="ABCD12"
              value={roomCodeInput}
              onChange={(e) => setRoomCodeInput(e.target.value)}
              maxLength={12}
            />
          </label>

          {error ? <p className="rounded-lg border border-red-500/40 bg-red-500/10 p-2 text-sm text-red-200">{error}</p> : null}

          <button
            type="submit"
            disabled={!canSubmit || loading}
            className="rounded-lg bg-gradient-to-r from-brand-600 to-indigo-500 px-4 py-2.5 font-bold text-white transition hover:from-brand-500 hover:to-indigo-400 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {loading ? 'Processing...' : 'Join Room'}
          </button>
        </form>
      </section>
    </AppShell>
  )
}

import { FormEvent, useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { useNavigate, useParams } from 'react-router-dom'
import { AppShell } from '../components/AppShell'
import { requestGuestToken } from '../services/authService'
import { joinRoom } from '../services/roomService'
import { useRoomStore } from '../store/useRoomStore'
import { useSessionStore } from '../store/useSessionStore'
import { normalizeRoomCode } from '../utils/roomCode'

export function JoinPage() {
  const params = useParams<{ roomCode?: string }>()
  const navigate = useNavigate()
  const [nickname, setNickname] = useState('')
  const [roomCodeInput, setRoomCodeInput] = useState(params.roomCode ?? '')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string>()

  const setSession = useSessionStore((s) => s.setSession)
  const setRoom = useRoomStore((s) => s.setRoom)

  const canSubmit = useMemo(() => nickname.trim().length >= 2 && roomCodeInput.trim().length >= 4, [nickname, roomCodeInput])

  const onSubmit = async (event: FormEvent) => {
    event.preventDefault()
    if (!canSubmit) {
      return
    }

    setError(undefined)
    setLoading(true)

    try {
      const room = await joinRoom(normalizeRoomCode(roomCodeInput), nickname.trim())
      const token = await requestGuestToken(nickname.trim(), room.code)
      const me = room.players.find((player) => player.nickname.toLowerCase() === nickname.trim().toLowerCase())

      setSession({
        nickname: nickname.trim(),
        roomCode: room.code,
        token: token.token,
        isHost: Boolean(me?.host),
        playerId: me?.id,
      })
      setRoom(room)
      navigate(`/room/${room.code}/waiting`)
    } catch (caught) {
      const message = caught instanceof Error ? caught.message : 'Không thể vào phòng'
      setError(message)
    } finally {
      setLoading(false)
    }
  }

  return (
    <AppShell title="Vào trò chơi" subtitle="Nhập tên và mã phòng để tham gia trò chơi.">
      <section className="mx-auto w-full max-w-xl">
        <form onSubmit={onSubmit} className="grid gap-4 rounded-2xl border border-slate-700 bg-slate-900/90 p-6">
          <p className="text-sm text-slate-400">
            Quản trị tạo phòng tại <Link to="/admin" className="text-brand-300 underline">/admin</Link>
          </p>
          <label className="grid gap-2">
            <span className="text-sm text-slate-300">Tên người chơi</span>
            <input
              className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 outline-none transition focus:border-brand-500"
              placeholder="Ví dụ: Captain_01"
              value={nickname}
              onChange={(e) => setNickname(e.target.value)}
              maxLength={30}
            />
          </label>

          <label className="grid gap-2">
            <span className="text-sm text-slate-300">Mã phòng</span>
            <input
              className="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 uppercase outline-none transition focus:border-brand-500"
              placeholder="ABCD12"
              value={roomCodeInput}
              onChange={(e) => setRoomCodeInput(e.target.value)}
              maxLength={12}
            />
          </label>

          {error ? <p className="rounded-lg border border-red-500/40 bg-red-500/10 p-2 text-sm text-red-200">{error}</p> : null}

          <button
            type="submit"
            disabled={!canSubmit || loading}
            className="rounded-lg bg-gradient-to-r from-brand-600 to-indigo-500 px-4 py-2.5 font-bold text-white transition hover:from-brand-500 hover:to-indigo-400 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {loading ? 'Đang xử lý...' : 'Vào phòng'}
          </button>
        </form>
      </section>
    </AppShell>
  )
}

import { useMemo } from 'react'
import { Link } from 'react-router-dom'
import { AppShell } from '../components/AppShell'
import { useGameStore } from '../store/useGameStore'
import { useRoomStore } from '../store/useRoomStore'

export function ResultPage() {
  const room = useRoomStore((s) => s.room)
  const isConnected = useGameStore((s) => s.isConnected)

  const ranking = useMemo(() => {
    if (!room) {
      return []
    }
    return [...room.players].sort((a, b) => b.score - a.score)
  }, [room])

  return (
    <AppShell
      title="Final Result"
      subtitle="Top players for this game session."
      roomCode={room?.code}
      phase="Completed"
      connected={isConnected}
    >
      <section className="rounded-2xl border border-slate-700 bg-slate-900/90 p-4">
        {ranking.length === 0 ? <p className="text-slate-400">No result yet.</p> : null}
        <ol className="space-y-2">
          {ranking.map((player, index) => (
            <li
              key={player.id}
              className={`flex items-center justify-between rounded-lg border p-3 ${
                index === 0
                  ? 'border-amber-300/50 bg-amber-500/15 text-amber-100'
                  : 'border-slate-700 bg-slate-800 text-slate-100'
              }`}
            >
              <span>
                #{index + 1} {player.nickname}
              </span>
              <span className="font-semibold">{player.score} pts</span>
            </li>
          ))}
        </ol>

        <Link
          to="/"
          className="mt-4 inline-block rounded-lg bg-gradient-to-r from-brand-600 to-indigo-500 px-4 py-2 font-semibold text-white hover:from-brand-500 hover:to-indigo-400"
        >
          Back to Join
        </Link>
      </section>
    </AppShell>
  )
}

