      </div>
    </AppShell>
  )
}

import { env } from '../config/env'
import type { ApiErrorResponse } from '../types/room'

export class ApiClientError extends Error {
  readonly status: number
  readonly response?: ApiErrorResponse

  constructor(status: number, message: string, response?: ApiErrorResponse) {
    super(message)
    this.status = status
    this.response = response
  }
}

export async function apiRequest<T>(path: string, options?: RequestInit): Promise<T> {
  let response: Response
  try {
    response = await fetch(`${env.apiBaseUrl}${path}`, {
      headers: {
        'Content-Type': 'application/json',
        ...(options?.headers ?? {}),
      },
      ...options,
    })
  } catch {
    throw new ApiClientError(0, 'Cannot connect to backend service. Please ensure backend is running.')
  }

  if (!response.ok) {
    const body = (await response.json().catch(() => undefined)) as ApiErrorResponse | undefined
    throw new ApiClientError(response.status, body?.message ?? 'Request failed', body)
  }

  return (await response.json()) as T
}

import { env } from '../config/env'
import type { ApiErrorResponse } from '../types/room'

export class ApiClientError extends Error {
  readonly status: number
  readonly response?: ApiErrorResponse

  constructor(status: number, message: string, response?: ApiErrorResponse) {
    super(message)
    this.status = status
    this.response = response
  }
}

export async function apiRequest<T>(path: string, options?: RequestInit): Promise<T> {
  let response: Response
  try {
    response = await fetch(`${env.apiBaseUrl}${path}`, {
      headers: {
        'Content-Type': 'application/json',
        ...(options?.headers ?? {}),
      },
      ...options,
    })
  } catch {
    throw new ApiClientError(0, 'Không thể kết nối đến dịch vụ backend. Vui lòng kiểm tra backend đang chạy.')
  }

  if (!response.ok) {
    const body = (await response.json().catch(() => undefined)) as ApiErrorResponse | undefined
    throw new ApiClientError(response.status, body?.message ?? 'Yêu cầu thất bại', body)
  }

  return (await response.json()) as T
}

import { Client } from '@stomp/stompjs'
import SockJS from 'sockjs-client'
import { env } from '../config/env'
import type { GameInboundMessage, GameOutboundMessage } from '../types/socket'

class SocketClient {
  private client: Client | null = null

  connect(onMessage: (message: GameOutboundMessage) => void, roomCode: string, token?: string): Promise<void> {
    if (this.client?.active) {
      return Promise.resolve()
    }

    return new Promise((resolve, reject) => {
      const client = new Client({
        webSocketFactory: () => new SockJS(env.wsUrl),
        reconnectDelay: 3000,
        connectHeaders: token ? { Authorization: `Bearer ${token}` } : {},
        onConnect: () => {
          client.subscribe(`/topic/rooms/${roomCode}`, (frame) => {
            onMessage(JSON.parse(frame.body) as GameOutboundMessage)
          })
          resolve()
        },
        onStompError: (frame) => {
          reject(new Error(frame.headers.message ?? 'WebSocket error'))
        },
      })

      client.activate()
      this.client = client
    })
  }

  publish(roomCode: string, message: GameInboundMessage): void {
    if (!this.client?.connected) {
      return
    }

    this.client.publish({
      destination: `/app/rooms/${roomCode}/event`,
      body: JSON.stringify(message),
    })
  }

  disconnect(): void {
    this.client?.deactivate()
    this.client = null
  }
}

export const socketClient = new SocketClient()

